  "python": "def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    args = json.loads(action.arguments)
    name = action.name
    if name == "researcher/collect":
        return None
    elif name == "buyer/collect":
        return None
    elif name == "buyer/submit":
        target = args.get("target")
        if target is None:
            raise PolicyViolation("buyer/submit missing target")
        if target == "order":
            if "UNVERIFIED" in label.subset:
                raise PolicyViolation("slot:order cannot contain UNVERIFIED")
        elif target == "supplier":
            if "CONFIDENTIAL" in label.subset:
                raise PolicyViolation("slot:supplier cannot contain CONFIDENTIAL")
        elif target == "review":
            pass
        elif target == "order_and_supplier":
            if "UNVERIFIED" in label.subset or "CONFIDENTIAL" in label.subset:
                raise PolicyViolation("slot:order cannot contain UNVERIFIED and slot:supplier cannot contain CONFIDENTIAL")
        else:
            raise PolicyViolation("unknown target for buyer/submit")
        return None
    else:
        raise PolicyViolation("unknown action")
